import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();

  const menuItems = [
    { name: "Home", route: "/" },
    { name: "Profile", route: "/profile" },
    { name: "Settings", route: "/settings" },
    { name: "About", route: "/about" },
    { name: "Logout", route: "/login" }
  ];

  return (
    <div className="homepage-container">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">🚗 Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className="sidebar-btn"
            onClick={() => {
              if (item.name === "Logout") localStorage.removeItem("user");
              navigate(item.route);
            }}
          >
            {item.name}
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <section className="hero-section">
          <h1>Welcome to Parking Slot System</h1>
          <p>Book your parking slots easily, track your bookings, and manage your profile all in one place.</p>
          <button className="start-btn" onClick={() => navigate("/booking")}>
            Start Booking
          </button>
        </section>

        <section className="dashboard-cards">
          <div className="card">
            <h2>Your Bookings</h2>
            <p>Check your current and upcoming bookings here.</p>
            <button onClick={() => navigate("/booking")}>View Bookings</button>
          </div>
          <div className="card">
            <h2>Available Slots</h2>
            <p>See how many parking slots are available right now.</p>
            <button onClick={() => navigate("/booking")}>View Slots</button>
          </div>
          <div className="card">
            <h2>Profile</h2>
            <p>Update your personal information and preferences.</p>
            <button onClick={() => navigate("/profile")}>Go to Profile</button>
          </div>
        </section>
      </main>
    </div>
  );
}

export default HomePage;
